    private const int IndentSize = 2;

    private static void Line(StringBuilder sb, int depth, string text) =>
        sb.AppendLine(new string(' ', Math.Max(0, depth) * IndentSize) + text);

    public static string GenerateSequenceDiagram(this Workflow workflow)
    {
        var plantUml = new StringBuilder();
        Line(plantUml, 0, "@startuml");
        Line(plantUml, 0, $"title {Escape(workflow.Name)} - {Escape(workflow.Version)}");
        Line(plantUml, 0, "autonumber");
        Line(plantUml, 0, "actor User");

        if (workflow.Steps is not { Count: > 0 })
        {
            Line(plantUml, 0, "@enduml");
            return plantUml.ToString();
        }

        foreach (var step in workflow.Steps)
        {
            Line(plantUml, 0, $"participant \"{Escape(step.Key)}\" as {Sanitize(step.Key)}");
        }

        var first = workflow.Steps.First();
        Line(plantUml, 0, $"User -> {Sanitize(first.Key)}: start");
        AppendSequenceFrom(plantUml, workflow, first.Key, [], "User", 0);
        Line(plantUml, 0, $"{Sanitize(first.Key)} --> User: done");
        Line(plantUml, 0, "@enduml");
        return plantUml.ToString();
    }

    private static void AppendSequenceFrom(
        StringBuilder plantUml,
        Workflow workflow,
        string stepName,
        HashSet<string> visited,
        string from,
        int depth)
    {
        if (IsTerminal(stepName))
        {
            Line(plantUml, depth, $"{Sanitize(from)} --> User: {Sanitize(stepName)}");
            return;
        }

        if (!workflow.Steps.TryGetValue(stepName, out var step) || !visited.Add(stepName))
        {
            return;
        }

        var self = Sanitize(stepName);

        if (step.IsParallelCoordinator)
        {
            Line(plantUml, depth, $"note right of {self}");
            Line(plantUml, depth + 1, $"parallel join={step.Join ?? "all"}");
            Line(plantUml, depth, "end note");
            Line(plantUml, depth, "par");
            for (var i = 0; i < step.Parallel.Count; i++)
            {
                if (i > 0)
                {
                    Line(plantUml, depth, "else");
                }

                var childName = step.Parallel[i];
                Line(plantUml, depth + 1, $"{self} -> {Sanitize(childName)}: {HttpLabel(workflow, childName)}");
            }

            Line(plantUml, depth, "end");
            AppendSequenceTransitions(plantUml, workflow, stepName, step, visited, depth);
            return;
        }

        if (step.IsForeachCoordinator)
        {
            var item = step.ForeachItemStep ?? "item";
            Line(plantUml, depth, $"note right of {self}");
            Line(plantUml, depth + 1, $"foreach {step.As ?? "item"} ({step.Mode ?? "sequential"})");
            Line(plantUml, depth, "end note");
            Line(plantUml, depth, $"loop foreach {Escape(step.As ?? "item")}");
            Line(plantUml, depth + 1, $"{self} -> {Sanitize(item)}: {HttpLabel(workflow, item)}");
            Line(plantUml, depth, "end");
            AppendSequenceTransitions(plantUml, workflow, stepName, step, visited, depth);
            return;
        }

        AppendSequenceNotes(plantUml, step, self, depth);
        AppendSequenceTransitions(plantUml, workflow, stepName, step, visited, depth);
    }

    private static void AppendSequenceTransitions(
        StringBuilder plantUml,
        Workflow workflow,
        string stepName,
        Step step,
        HashSet<string> visited,
        int depth)
    {
        if (step.Transitions is not { Count: > 0 })
        {
            return;
        }

        var self = Sanitize(stepName);
        if (step.Transitions.Count == 1)
        {
            var next = step.Transitions[0].Action;
            if (!IsTerminal(next) && workflow.Steps.ContainsKey(next))
            {
                Line(plantUml, depth, $"{self} -> {Sanitize(next)}: {Escape(step.Transitions[0].Condition)}");
            }

            AppendSequenceFrom(plantUml, workflow, next, visited, stepName, depth);
            return;
        }

        for (var i = 0; i < step.Transitions.Count; i++)
        {
            var transition = step.Transitions[i];
            Line(plantUml, depth, $"{(i == 0 ? "alt" : "else")} {Escape(transition.Condition)}");
            if (!IsTerminal(transition.Action) && workflow.Steps.ContainsKey(transition.Action))
            {
                Line(plantUml, depth + 1, $"{self} -> {Sanitize(transition.Action)}: {HttpLabel(workflow, transition.Action)}");
            }

            AppendSequenceFrom(plantUml, workflow, transition.Action, visited, stepName, depth + 1);
        }

        Line(plantUml, depth, "end");
    }

    private static string HttpLabel(Workflow workflow, string stepName)
    {
        if (!workflow.Steps.TryGetValue(stepName, out var step) || step.IsCoordinator)
        {
            return Escape(stepName);
        }

        var method = string.IsNullOrWhiteSpace(step.Method) ? "HTTP" : step.Method.ToUpperInvariant();
        return $"{method} {Escape(stepName)}";
    }

    private static void AppendSequenceNotes(StringBuilder plantUml, Step currentStep, string stepName, int depth)
    {
        Line(plantUml, depth, $"note right of {stepName}");
        if (currentStep.IsParallelCoordinator)
        {
            Line(plantUml, depth + 1, $"parallel join={currentStep.Join ?? "all"}");
            foreach (var child in currentStep.Parallel)
            {
                Line(plantUml, depth + 1, $"- {child}");
            }
        }
        else if (currentStep.IsForeachCoordinator)
        {
            Line(plantUml, depth + 1, $"foreach: {currentStep.Foreach}");
            Line(plantUml, depth + 1, $"as: {currentStep.As ?? "item"}");
            Line(plantUml, depth + 1, $"mode: {currentStep.Mode ?? "sequential"}");
            Line(plantUml, depth + 1, $"item step: {currentStep.ForeachItemStep}");
        }
        else
        {
            Line(plantUml, depth + 1, $"API: {currentStep.Url}");
            if (currentStep.Headers is { Count: > 0 })
            {
                Line(plantUml, depth + 1, "Headers:");
                foreach (var header in currentStep.Headers)
                {
                    Line(plantUml, depth + 2, $"- {header.Key}: {header.Value}");
                }
            }

            if (currentStep.Body is { Count: > 0 })
            {
                Line(plantUml, depth + 1, "Body:");
                foreach (var body in currentStep.Body)
                {
                    Line(plantUml, depth + 2, $"- {body.Key}: {body.Value}");
                }
            }
        }

        Line(plantUml, depth, "end note");
    }

    public static string GenerateStateMachineDiagram(this Workflow workflow)
    {
        var plantUML = new StringBuilder();
        Line(plantUML, 0, "@startuml");
        Line(plantUML, 0, $"title {Escape(workflow.Name)} - {Escape(workflow.Version)}");
        plantUML.AppendLine();

        if (workflow.Steps is not { Count: > 0 })
        {
            Line(plantUML, 0, "@enduml");
            return plantUML.ToString();
        }

        foreach (var stepName in workflow.Steps.Keys)
        {
            Line(plantUML, 0, $"state {Sanitize(stepName)} as \"{Escape(stepName)}\"");
        }

        Line(plantUML, 0, "[*] --> " + Sanitize(workflow.Steps.First().Key));
        foreach (var (stepName, step) in workflow.Steps)
        {
            var self = Sanitize(stepName);
            if (step.IsParallelCoordinator)
            {
                var fork = $"fork_{self}";
                var join = $"join_{self}";
                Line(plantUML, 0, $"state {fork} <<fork>>");
                Line(plantUML, 0, $"state {join} <<join>>");
                Line(plantUML, 0, $"{self} --> {fork}");
                foreach (var child in step.Parallel)
                {
                    Line(plantUML, 1, $"{fork} --> {Sanitize(child)}");
                    Line(plantUML, 1, $"{Sanitize(child)} --> {join}");
                }

                AppendStateTransitions(plantUML, join, step, 0);
                continue;
            }

            if (step.IsForeachCoordinator && !string.IsNullOrWhiteSpace(step.ForeachItemStep))
            {
                Line(plantUML, 0, $"{self} --> {Sanitize(step.ForeachItemStep)} : foreach item");
                Line(plantUML, 0, $"{Sanitize(step.ForeachItemStep)} --> {self} : next item");
                AppendStateTransitions(plantUML, self, step, 0);
                continue;
            }

            AppendStateTransitions(plantUML, self, step, 0);
        }

        Line(plantUML, 0, "@enduml");
        return plantUML.ToString();
    }

    private static void AppendStateTransitions(StringBuilder plantUML, string fromState, Step step, int depth)
    {
        if (step.Transitions is not { Count: > 0 })
        {
            return;
        }

        foreach (var onSuccess in step.Transitions)
        {
            var target = IsTerminal(onSuccess.Action) ? "[*]" : Sanitize(onSuccess.Action);
            Line(plantUML, depth, $"{fromState} --> {target} : {Escape(onSuccess.Condition)}");
        }
    }

    public static string GenerateActivityDiagram(this Workflow workflow)
    {
        var plantUML = new StringBuilder();
        Line(plantUML, 0, "@startuml");
        Line(plantUML, 0, $"title {Escape(workflow.Name)} — Flowchart");
        Line(plantUML, 0, "start");

        if (workflow.Steps is not { Count: > 0 })
        {
            Line(plantUML, 0, "stop");
            Line(plantUML, 0, "@enduml");
            return plantUML.ToString();
        }

        // Walk the happy path linearly. At each branching step emit if/else so fail
        // ends with `stop` (not kill/detach — those break open if-chains in PlantUML).
        var visited = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var current = workflow.Steps.First().Key;
        var depth = 0;

        while (!string.IsNullOrWhiteSpace(current) && !IsTerminal(current))
        {
            if (!visited.Add(current))
            {
                Line(plantUML, depth, $":{Escape(current)} (already visited);");
                break;
            }

            if (!workflow.Steps.TryGetValue(current, out var step))
            {
                Line(plantUML, depth, $":{Escape(current)};");
                break;
            }

            AppendActivityStep(plantUML, current, step, depth);

            var transitions = step.Transitions;
            if (transitions is not { Count: > 0 })
            {
                break;
            }

            if (transitions.Count == 1)
            {
                current = transitions[0].Action;
                continue;
            }

            var continueTransition = transitions.FirstOrDefault(t => !IsFailTerminal(t.Action));
            var hasFail = transitions.Any(t => IsFailTerminal(t.Action));

            // Common shape: one continue path + fail/default → flat if/else.
            if (continueTransition != null && hasFail &&
                transitions.Count(t => !IsFailTerminal(t.Action)) == 1)
            {
                Line(plantUML, depth, $"if ({Escape(continueTransition.Condition)}) then (yes)");
                Line(plantUML, depth, "else (fail)");
                Line(plantUML, depth + 1, ":Fail;");
                Line(plantUML, depth + 1, "stop");
                Line(plantUML, depth, "endif");
                current = continueTransition.Action;
                continue;
            }

            // Multi-way split: if / elseif / else, fail branches stop, primary continues.
            var continueIndex = continueTransition == null ? -1 : transitions.IndexOf(continueTransition);
            for (var i = 0; i < transitions.Count; i++)
            {
                var transition = transitions[i];
                var isLast = i == transitions.Count - 1;
                if (i == 0)
                {
                    Line(plantUML, depth, $"if ({Escape(transition.Condition)}) then (yes)");
                }
                else if (!isLast)
                {
                    Line(plantUML, depth, $"elseif ({Escape(transition.Condition)}) then (yes)");
                }
                else
                {
                    Line(plantUML, depth, $"else ({Escape(ShortLabel(transition.Condition))})");
                }

                if (IsFailTerminal(transition.Action))
                {
                    Line(plantUML, depth + 1, ":Fail;");
                    Line(plantUML, depth + 1, "stop");
                }
                else if (IsSuccessTerminal(transition.Action))
                {
                    Line(plantUML, depth + 1, ":Success;");
                    Line(plantUML, depth + 1, "stop");
                }
                else if (i == continueIndex)
                {
                    // Happy-path branch stays open; steps continue after endif.
                }
                else
                {
                    Line(plantUML, depth + 1, $":{Escape(transition.Action)};");
                    Line(plantUML, depth + 1, "stop");
                }
            }

            Line(plantUML, depth, "endif");
            current = continueTransition?.Action ?? transitions[0].Action;
            if (continueTransition == null || IsTerminal(current))
            {
                break;
            }
        }

        if (IsFailTerminal(current))
        {
            Line(plantUML, depth, ":Fail;");
        }
        else
        {
            Line(plantUML, depth, ":Success;");
        }

        Line(plantUML, depth, "stop");
        Line(plantUML, 0, "@enduml");
        return plantUML.ToString();
    }

    private static void AppendActivityStep(StringBuilder plantUML, string stepName, Step step, int depth)
    {
        if (step.IsParallelCoordinator)
        {
            Line(plantUML, depth, $":{Escape(stepName)} (parallel);");
            Line(plantUML, depth, "fork");
            for (var i = 0; i < step.Parallel.Count; i++)
            {
                if (i > 0)
                {
                    Line(plantUML, depth, "fork again");
                }

                Line(plantUML, depth + 1, $":{Escape(step.Parallel[i])};");
            }

            Line(plantUML, depth, "end fork");
            return;
        }

        if (step.IsForeachCoordinator)
        {
            Line(plantUML, depth, $"while ({Escape(stepName)} foreach) is (has item)");
            Line(plantUML, depth + 1, $":{Escape(step.ForeachItemStep)};");
            Line(plantUML, depth, "endwhile (done)");
            return;
        }

        Line(plantUML, depth, $":{Escape(stepName)};");
        if (step.Body is not { Count: > 0 })
        {
            return;
        }

        Line(plantUML, depth, "note right");
        var count = 0;
        foreach (var bodyParam in step.Body)
        {
            Line(plantUML, depth + 1, $"{Escape(bodyParam.Key)} = {Escape(bodyParam.Value?.ToString())}");
            if (++count >= 8)
            {
                Line(plantUML, depth + 1, "...");
                break;
            }
        }

        Line(plantUML, depth, "end note");
    }

    private static bool IsFailTerminal(string action) =>
        action.Equals("fail", StringComparison.OrdinalIgnoreCase);

    private static bool IsSuccessTerminal(string action) =>
        action.Equals("success", StringComparison.OrdinalIgnoreCase)
        || action.Equals("end", StringComparison.OrdinalIgnoreCase);

    private static string ShortLabel(string? condition)
    {
        var text = Escape(condition);
        return text.Length <= 40 ? text : text[..37] + "...";
    }

    public static string GetPlantUml(this Workflow workflow)
    {
        return workflow.GenerateActivityDiagram();
    }

    public static string GetEncodedPlantUml(this Workflow workflow)
    {
        var umlCode = workflow.GenerateSequenceDiagram();
        byte[] data = System.Text.Encoding.UTF8.GetBytes(umlCode);
        using (var output = new MemoryStream())
        {
            using (var compressor =
                   new System.IO.Compression.DeflateStream(output, System.IO.Compression.CompressionLevel.Optimal,
                       true))
            {
                compressor.Write(data, 0, data.Length);
            }

            return Encode64(output.ToArray());
        }
    }

    private static bool IsTerminal(string action) =>
        string.IsNullOrWhiteSpace(action)
        || action.Equals("success", StringComparison.OrdinalIgnoreCase)
        || action.Equals("end", StringComparison.OrdinalIgnoreCase)
        || action.Equals("fail", StringComparison.OrdinalIgnoreCase);

    private static string Sanitize(string? input)
    {
        var value = new string((input ?? string.Empty)
            .Where(ch => char.IsLetterOrDigit(ch) || ch is '_').ToArray());
        return string.IsNullOrEmpty(value) ? "step" : value;
    }

    private static string Escape(string? input) =>
        (input ?? string.Empty)
            .Replace("\"", "'")
            .Replace("{", "(")
            .Replace("}", ")")
            .Replace("\n", " ");

    private static string Encode64(byte[] data)
    {
        const string encodeTable = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz-_";
        var builder = new System.Text.StringBuilder();
        uint buffer = 0;
        int bitsInBuffer = 0;

        foreach (byte b in data)
        {
            buffer = (buffer << 8) | b;
            bitsInBuffer += 8;

            while (bitsInBuffer >= 6)
            {
                bitsInBuffer -= 6;
                var index = (buffer >> bitsInBuffer) & 0x3F;

                if (index < 0 || index >= encodeTable.Length)
                    throw new InvalidOperationException("Buffer out of bounds.");

                builder.Append(encodeTable[(int)index]);
            }
        }

        if (bitsInBuffer > 0)
        {
            buffer <<= (6 - bitsInBuffer);
            var index = buffer & 0x3F;

            if (index < 0 || index >= encodeTable.Length)
                throw new InvalidOperationException("Remaining buffer out of bounds.");

            builder.Append(encodeTable[(int)index]);
        }

        return builder.ToString();
    }
